    'remoteEntry.json',
    'importmap.json',
    'ngsw.json',
    'ngsw-worker.js',
    'safety-worker.js',
    'worker-basic.min.js',
    'manifest.webmanifest',
    'favicon.ico',
    'icons',
    'icons/*',
  ],
});

const tags: Tags = Tags.of(app);
tags.add('app', 'BacteriaGame');
